from ..ordering import out_of_order

def sort2(x, y):
    if out_of_order(x, y):
        return y, x
    return x, y

# %% ../../nbs/02_sequences/04_sorting/02_adjacent-exchange.ipynb #da213bba
def sort3(x, y, z):
    x, y = sort2(x, y)
    y, z = sort2(y, z)
    x, y = sort2(x, y)
    return x, y, z

# %% ../../nbs/02_sequences/04_sorting/02_adjacent-exchange.ipynb #c16fa16d
def bubble_pass(a, first, last):
    for i in range(first, last - 1):
        a[i], a[i + 1] = sort2(a[i], a[i + 1])

def bubble_sort(a, first, last):
    while last - first > 1:
        bubble_pass(a, first, last)
        last -= 1

